def _inline_r_setup(code: str) -> str:
    """
    Some behaviour of R cannot be configured via env variables, but can
    only be configured via R options once R has started. These are set here.
    """
    code = code.strip()
    if not code:
        return ""

    opt_set = re.compile(r"^options\((.*?)([=])(.+)\)$", re.MULTILINE)
    matches = re.findall(opt_set, code)

    for m in matches:
        if m[1] == "=":
            code = code.replace(m[0], f"options(c({m[0]})=c({m[2]}))")
        else:
            code = code.replace(m[0], f"options(c({m[0]}){m[1]}c({m[2]}))")

    return code.strip()

def xargs(cmd, varargs, *, color=False, target_concurrency=1, _max_length=_get_platform_max_length(), **kwargs):
    """A simplified implementation of xargs.

    color: Make a pty if on a platform that supports it
    target_concurrency: Target number of partitions to run concurrently
    """
    # Handle potential invalid inputs
    if not isinstance(cmd, tuple) or not all(isinstance(x, str) for x in cmd):
        raise TypeError("cmd must be a tuple of strings")
    if not isinstance(varargs, Sequence) or not all(isinstance(x, str) for x in varargs):
        raise TypeError("varargs must be a sequence of strings")
    if not isinstance(color, bool):
        raise TypeError("color must be a boolean")
    if not isinstance(target_concurrency, int):
        raise TypeError("target_concurrency must be an integer")
    if not isinstance(_max_length, int):
        raise TypeError("_max_length must be an integer")

    # Handle runtime issues with exception-handling behavior
    try:
        cmd = parse_shebang.normalize_cmd(cmd)
    except parse_shebang.ExecutableNotFoundError as e:
        return e.to_output()

    partitions = partition(cmd, varargs, target_concurrency, _max_length)

    def run_cmd_partition(run_cmd):
        return cmd_output(*run_cmd, encoding=None, retcode=None, **kwargs)

    threads = min(len(partitions), target_concurrency)
    with _thread_mapper(threads) as thread_map:
        results = thread_map(run_cmd_partition, partitions)

    retcode = 0
    stdout = b''
    stderr = b''
    for proc_retcode, proc_out, proc_err in results:
        retcode |= proc_retcode
        stdout += proc_out
        stderr += proc_err

    return retcode, stdout, stderr

def xargs(cmd, varargs, *, color=False, target_concurrency=1, _max_length=_get_platform_max_length(), **kwargs):
    negate = kwargs.pop('negate', False)
    target_concurrency = min(target_concurrency, len(cmd))
    retcode = 0
    stdout = b''
    stderr = b''

    try:
        cmd = parse_shebang.normalize_cmd(cmd)
    except parse_shebang.ExecutableNotFoundError as e:
        return e.to_output()

    partitions = partition(cmd, varargs, target_concurrency, _max_length)

    def run_cmd_partition(run_cmd):
        return cmd_output(*run_cmd, encoding=None, retcode=None, **kwargs)

    threads = min(len(partitions), target_concurrency)
    with _thread_mapper(threads) as thread_map:
        results = thread_map(run_cmd_partition, partitions)

        for proc_retcode, proc_out, proc_err in results:
            retcode |= bool(proc_retcode) ^ negate
            stdout += proc_out
            stderr += proc_err

    return retcode, stdout, stderr

