def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    try:
        s = s.strip() if isinstance(s, str) else ''
        major, minor, patch = (0, 0, 0)
        for i, part in enumerate(s.split('.')):
            if i == 0:
                major = int(part)
            elif i == 1:
                minor = int(part)
            elif i == 2:
                patch = int(part)
            else:
                break
        return (major, minor, patch)
    except ValueError:
        return (0, 0, 0)

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    # Handle potential invalid inputs
    if not isinstance(s, str):
        raise ValueError(f'Input must be a string, got {type(s)}')
    if not s:
        raise ValueError('Input string cannot be empty')
    # Use regular expressions to parse the version string
    m = re.match(r'^v?(?P<major>\d+)(?:\.(?P<minor>\d+)(?:\.(?P<patch>\d+))*)?', s)
    if m is None:
        raise ValueError(f'Invalid version string: {s}')
    # Extract version parts and convert them to integers
    try:
        major = int(m.group('major'))
        minor = int(m.group('minor'))
        patch = int(m.group('patch')) if m.group('patch') is not None else 0
    except ValueError as e:
        raise ValueError(f'Invalid version parts: {e}') from e
    # Return a tuple with the version parts
    return (major, minor, patch)

