def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    self._context = {}
    if self._initial_value is not None:
        self._bins = self._make_bins(self._initial_value)
    else:
        self._bins = self._make_bins()

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    if coord_name not in self.coords:
        raise ValueError(f"Coordinate {coord_name} not found.")

    coord_index = self.coords.index(coord_name)
    err_indices = []
    for i, (index_name, index_value) in enumerate(self.indexes.items()):
        if index_name == coord_name:
            err_indices.append(i)

    return err_indices

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    try:
        coord = self._coords[coord_name]
        err_indices = np.where(coord.error != 0)[0]
        return err_indices
    except KeyError:
        raise KeyError("Coordinate '{0}' not found in data.".format(coord_name))

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    if coord_name not in self.coords:
        raise KeyError(f"Coordinate '{coord_name}' not found.")
    coord = self.coords[coord_name]
    if coord.err is None:
        return []
    err = coord.err[self.index]
    return np.where(np.isnan(err))[0]

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    if coord_name not in self.coords.keys():
        raise ValueError("Coordinate name {!r} does not exist.".format(coord_name))

    coord_data = self.coords[coord_name]

    if 'error' not in coord_data.dims:
        raise ValueError("Coordinate {!r} does not have error values.".format(coord_name))

    err_indices = np.where(coord_data.error.values == 0)[0]

    if len(err_indices) == 0:
        raise ValueError("Coordinate {!r} has no error values.".format(coord_name))

    return err_indices

def _update_context(self, context):
    if not hasattr(self, 'error'):
        return
    for ekey, evalue in self.error.items():
        if ekey not in context.error:
            context.error[ekey] = {}
        context.error[ekey]["index"] = evalue
        for k in self.keys():
            if k not in context.value:
                context.value[k] = {}
            context.value[k]["index"] = self[k]

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    if len(bins) != len(edges) - 1:
        raise ValueError("Incorrect number of bins")
    return sum((edges[i + 1] - edges[i]) * bins[i] for i in range(len(bins)))

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    total = 0
    for i, bin in enumerate(bins):
        if i == 0:
            width = edges[i+1] - edges[i]
        elif i == len(bins) - 1:
            width = edges[-1] - edges[-2]
        else:
            width = (edges[i+1] - edges[i-1]) / 2
        total += bin * width
    return total

