def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if level == 0:
        return d1
    if level == -1:
        for key, value in d1.items():
            if key not in d2 or value != d2[key]:
                return {key: value}
        return {}
    else:
        diff = {}
        for key, value in d1.items():
            if key not in d2 or value != d2[key]:
                diff[key] = value
            elif isinstance(value, dict):
                diff[key] = difference(value, d2[key], level - 1)
        return diff

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if level == 1:
        if not isinstance(d1, dict) or not isinstance(d2, dict):
            raise ValueError("level 1 only supported for dictionaries")
        return {k: v for k, v in d1.items() if k not in d2 or d1[k] != d2[k]}
    if level == 0 or not isinstance(d1, dict):
        return d1
    return {k: difference(v, d2, level-1) for k, v in d1.items() if k not in d2 or not difference(v, d2[k], level-1)}

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    # First, we need to define the helper function that will perform the recursion
    def difference_helper(d1, d2, level):
        # This function assumes that d1 and d2 are dictionaries
        if level == 0:
            # We have reached the maximum level of recursion, so we just return the original dictionaries
            return d1, d2
        else:
            # We haven't reached the maximum level of recursion yet, so we need to recurse deeper
            new_d1 = {}
            new_d2 = {}
            for key in d1:
                if key in d2:
                    # If the key is present in both dictionaries, we recursively call the function for its value
                    new_d1[key], new_d2[key] = difference_helper(d1[key], d2[key], level - 1)
                else:
                    # If the key is present only in d1, we keep it in the difference
                    new_d1[key] = d1[key]
            return new_d1, new_d2

    # Now, we call the helper function to perform the recursion
    return difference_helper(d1, d2, level)

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if d1 is d2:
        return {}
    if level == 0:
        return d1
    diff = {}
    for k, v in d1.items():
        if k not in d2:
            diff[k] = v
        else:
            v2 = d2[k]
            if type(v) != type(v2):
                diff[k] = v
            elif isinstance(v, dict):
                dv = difference(v, v2, level-1)
                if dv:
                    diff[k] = dv
    return diff

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if level == 0:
        return d1
    if level == 1:
        diff = {}
        for key, value in d1.items():
            if key not in d2 or d2[key] != value:
                diff[key] = value
        return diff
    else:
        diff = {}
        for key in d1:
            if key not in d2:
                diff[key] = d2[key]
            elif level > 1:
                subdiff = difference(d1[key], d2[key], level - 1)
                if subdiff:
                    diff[key] = subdiff
        return diff

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """

    if not 0 <= coord[0] <= 1 or not 0 <= coord[1] <= 1:
        return

    if weight > 0:
        self.mesh[coord] += weight
    else:
        self.mesh[coord] = 0

def fill(self, coord, weight=1):
    """
    Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if not self._bin_edges:
        raise ValueError("Histogram must be initialized before filling")

    for (edge, bin) in zip(self._bin_edges, self._bins):
        if coord <= edge:
            bin.add(weight)
            return

    # If no bin was filled, we're outside the histogram edges:
    raise ValueError("Coordinate {c} outside histogram edges".format(c=coord))

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """
    import re
    from typing import Dict

    patterns = {
        "key": re.compile(r"^[a-zA-Z_]\w{0,}$"),
        "value": re.compile(r"^[^\s]+$"),
        "$$": re.compile(r"^\$")
    }

    errors = []
    for key, value in labels.items():
        if not isinstance(key, str):
            errors.append({key: f"expected string or bytes-like object"})

        if not isinstance(value, str):
            errors.append({key: f"expected string or bytes-like object"})

        for pattern_name, pattern in patterns.items():
            if pattern_name == "key" and not pattern.match(key):
                errors.append({key: f"Label key '{key}' does not match the regex {pattern.pattern}"})

            if pattern_name == "value" and not pattern.match(value):
                errors.append({value: f"expected string or bytes-like object"})

            if pattern_name == "$$" and not pattern.match(key):
                errors.append({key: f"Label key '{key}' does not match the regex {pattern.pattern}"})

    if errors:
        raise ValidationError(messages=errors)

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """
    ERROR_MESSAGES = {
        "key1": r'expected string or bytes-like object',
        "key2": r'expected string or bytes-like object',
        "$$": r'Label key '$$' does not match the regex [...]',
        True: r'expected string or bytes-like object',
        False: r'expected string or bytes-like object',
    }

    messages = []
    for label_key, label_val in labels.items():
        if isinstance(label_key, str):
            if not label_key.isalpha():
                messages.append({label_key: ERROR_MESSAGES.get(label_key, 'Invalid label key.')})
        else:
            messages.append({label_key: ERROR_MESSAGES.get(label_key, 'Invalid label key.')})

        if isinstance(label_val, str):
            if not label_val.isalpha():
                messages.append({label_val: ERROR_MESSAGES.get(label_val, 'Invalid label value.')})
        else:
            messages.append({label_val: ERROR_MESSAGES.get(label_val, 'Invalid label value.')})

    if messages:
        raise ValidationError(messages)

def validate_value(value):
    """Validate the given value against the corresponding regular expression.

    Args:
        value: The string to validate.

    Raises:
        ValidationError: If the given value is not conform to the regular expression.
    """
    try:
        if not re.match(pattern, value):
            raise ValidationError(f"{value} does not match the pattern {pattern}")
    except ValueError:
        raise ValidationError(f"{value} is not a valid string.")

