def update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, response):
    # Recursively update a partial `last_applied_manifest` from a partial Kubernetes response
    for i, (observed_field, observed_type) in enumerate(observer_schema):
        if observed_field not in last_applied_manifest:
            last_applied_manifest[observed_field] = None
        if observed_type == "list":
            update_last_applied_manifest_list_from_resp(last_applied_manifest[observed_field], observed_schema[observed_field], response[i])
        elif observed_type == "dict":
            update_last_applied_manifest_dict_from_resp(last_applied_manifest[observed_field], observed_schema[observed_field], response[i])
        else:
            last_applied_manifest[observed_field] = response[i]

def update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, response):
    for idx, sub_observer_schema in enumerate(observer_schema):
        if idx >= len(last_applied_manifest):
            last_applied_manifest.append([])
        update_last_applied_manifest_list_from_resp(last_applied_manifest[idx], sub_observer_schema, response[idx])

def update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, response):
    for i in range(len(response)):
        if isinstance(response[i], list):
            if i >= len(last_applied_manifest):
                last_applied_manifest.append([])
            update_last_applied_manifest_list_from_resp(last_applied_manifest[i], observer_schema[i], response[i])
        else:
            if i >= len(last_applied_manifest):
                last_applied_manifest.append(None)
            last_applied_manifest[i] = response[i]

def update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, response):
    for i in range(len(response)):
        last_applied_manifest[i] = update_last_applied_manifest_dict_from_resp(last_applied_manifest[i], observer_schema[i], response[i])
    return last_applied_manifest

def update_last_applied_manifest_dict_from_resp(last_applied_manifest, observer_schema, response):
    for field, field_schema in observer_schema.items():
        if field not in response:
            raise KeyError(f"Observed field {field} is not present in the Kubernetes response")
        value = response[field]
        if isinstance(field_schema, dict):
            if field not in last_applied_manifest:
                last_applied_manifest[field] = {}
            update_last_applied_manifest_dict_from_resp(last_applied_manifest[field], field_schema, value)
        else:
            last_applied_manifest[field] = value

def update_last_applied_manifest_dict_from_resp(last_applied_manifest, observer_schema, response):
    """
    Together with :func:``update_last_applied_manifest_list_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response
    """
    for key, value in observer_schema.items():
        if isinstance(value, dict):
            if key not in last_applied_manifest:
                last_applied_manifest[key] = {}
            update_last_applied_manifest_dict_from_resp(last_applied_manifest[key], value, response[key])
        elif isinstance(value, list):
            if key not in last_applied_manifest:
                last_applied_manifest[key] = []
            update_last_applied_manifest_list_from_resp(last_applied_manifest[key], value, response[key])
        else:
            if key not in last_applied_manifest:
