def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    for fixity_file in fixity:
        if fixity_file not in manifest_files:
            raise ValueError(f"File {fixity_file} is not listed in the manifest.")

        if not isinstance(fixity[fixity_file], dict):
            raise ValueError(f"Fixity entry for {fixity_file} is not a dict.")

        for algo in fixity[fixity_file]:
            if algo not in HASH_ALGORITHMS:
                raise ValueError(f"Unknown algorithm {algo} for file {fixity_file}.")

            if not isinstance(fixity[fixity_file][algo], str):
                raise ValueError(f"Fixity entry for {algo} in file {fixity_file} is not a string.")

