    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise TypeError("Fixity block must be a dictionary")

    for algo, values in fixity.items():
        if not isinstance(algo, str):
            raise TypeError("Fixity algorithm must be a string")
        if not isinstance(values, list):
            raise TypeError("Fixity values must be a list")

        for value in values:
            if not isinstance(value, str):
                raise TypeError("Fixity value must be a string")

            if value not in manifest_files:
                raise ValueError(f"File {value} not found in manifest")

    return True

