def _extract_number_and_supplment_from_issue_element(issue):
    number = None
    supplement = None

    issue_text = issue.text.strip()
    if issue_text.isdigit():
        number = int(issue_text)
    else:
        match = re.match(r'(\d+)(\s*[spe.](\s*\d+)?)', issue_text, re.I)
        if match:
            number = int(match.group(1))
            supplement = match.group(3)
            if supplement:
                supplement = supplement.strip()
        else:
            match = re.match(r'([spe]{2,}|\d+)', issue_text, re.I)
            if match:
                number = int(match.group(1))

    return number, supplement

