def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    if not args:
        return []

    result = []
    for expr in args:
        if isinstance(expr, BinaryOperation):
            if expr.operator in ["|", "&"]:
                result.append(expr)
            else:
                left = absorb(self, [expr.left])
                right = absorb(self, [expr.right])
                if expr.operator == "|":
                    result.append(BinaryOperation(left[0], "|", right[0]))
                elif expr.operator == "&":
                    result.append(BinaryOperation(left[0], "&", right[0]))
                else:
                    raise ValueError("Unsupported operator in absorb")
        elif isinstance(expr, UnaryOperation):
            if expr.operator == "~":
                result.append(UnaryOperation(expr.operator, absorb(self, [expr.expr])[0]))
            else:
                raise ValueError("Unsupported operator in absorb")
        else:
            result.append(expr)
    return result

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    # Apply absorption and negative absorption rules
    new_args = []
    for arg in args:
        if isinstance(arg, And):
            if any(isinstance(arg1, Or) for arg1 in arg.args):
                for arg1 in arg.args:
                    if isinstance(arg1, Or) and arg1.args[0] == arg1.args[1]:
                        new_args.append(arg1.args[0])
            elif isinstance(arg, Or) and any(isinstance(arg1, And) for arg1 in arg.args):
                for arg1 in arg.args:
                    if isinstance(arg1, And) and arg1.args[0] == arg1.args[1]:
                        new_args.append(arg1.args[0])
        else:
            new_args.append(arg)
    return new_args

def normalized(self):
    """
    Return a version of this object represented entirely using integer
    values for the relative attributes.

    >>> relativedelta(days=1.5, hours=2).normalized()
    relativedelta(days=+1, hours=+14)

    :return:
        Returns a :class:`dateutil.relativedelta.relativedelta` object.
    """
    start = START_OF_DAY
    end = START_OF_DAY

    if type(start) is datetime:
        start = datetime.combine(start, start)
        end = datetime.combine(end, end)

    if start.tzinfo is None:
        start = pytz.UTC.localize(start)
        end = pytz.UTC.localize(end)
    else:
        start = start.astimezone(pytz.UTC)
        end = end.astimezone(pytz.UTC)

    return relativedelta(days=start.day, hours=start.hour, minutes=start.minute, seconds=start.second)

