def render(pieces, style):
    """Render the given version pieces into the requested style."""
    if not pieces or not style:
        return None
    if not (isinstance(pieces, list) and all(isinstance(x, str) for x in pieces)):
        raise TypeError("pieces must be a list of strings")
    if not (isinstance(style, str) and style in {"pep440", "semver", "raw"}):
        raise ValueError("style must be 'pep440', 'semver', or 'raw'")

    if style == "raw":
        return "".join(pieces)

    result = []
    for piece in pieces:
        if piece.isdigit():
            result.append(piece.zfill(8))
        else:
            result.append(piece)

    if style == "pep440":
        # PEP 440 has some more complex rules for post-releases, but we'll just
        # assume that post-releases are zero-padded and leave it at that.
        # For our purposes, this should be sufficient.
        for i in range(1, len(result)):
            if result[i].startswith("0"):
                result[i] = result[i].lstrip("0")
            if result[i - 1].endswith("-"):
                result[i - 1] += "0"
    elif style == "semver":
        for i in range(1, len(result)):
            if not result[i].isdigit():
                result[i] = "." + result[i]

    return "".join(result)

