    unique_content_digests = set()
    for version_dir in version_dirs:
        inventory_path = os.path.join(version_dir, "inventory.json")
        inventory = json.load(open(inventory_path))
        for content_digest in inventory["content_digests"]:
            if content_digest not in unique_content_digests:
                unique_content_digests.add(content_digest)

    # Check that the root inventory has all the content digests
    root_inventory_path = os.path.join(version_dirs[0], "inventory.json")
    root_inventory = json.load(open(root_inventory_path))
    for content_digest in unique_content_digests:
        if content_digest not in root_inventory["content_digests"]:
