def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if padding is not None and padding < 1:
        raise ValueError("padding must be a positive integer")

    if len(alphabet) < 2:
        raise ValueError("alphabet must contain at least 2 symbols")

    result = ""
    if number == 0:
        result = alphabet[0]
    else:
        base = len(alphabet)
        while number > 0:
            remainder = number % base
            number = number // base
            result = alphabet[remainder] + result

    if padding is not None:
        result = result.rjust(padding, alphabet[0])

    return result

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not number:
        return "0"
    if padding is None:
        padding = len(alphabet)
    base = len(alphabet)
    result = []
    while number:
        number, remainder = divmod(number, base)
        result.append(alphabet[remainder])
    result.extend(alphabet[0] * (padding - len(result)))
    return "".join(reversed(result))

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if padding is None:
        padding = len(alphabet)
    base = len(alphabet)
    result = ""
    while number > 0:
        number, remainder = divmod(number, base)
        result = alphabet[remainder] + result
    return result.zfill(padding)

