def parse_frequency(frequency):
    if frequency is None or frequency.lower() == "always":
        return None
    try:
        number, unit = frequency.split(" ")
        if unit == "weeks":
            return datetime.timedelta(weeks=int(number))
        elif unit == "days":
            return datetime.timedelta(days=int(number))
        elif unit == "hours":
            return datetime.timedelta(hours=int(number))
        elif unit == "minutes":
            return datetime.timedelta(minutes=int(number))
        elif unit == "seconds":
            return datetime.timedelta(seconds=int(number))
        else:
            raise ValueError("Invalid unit of time")
    except ValueError:
        raise ValueError("Cannot parse frequency")

def parse_frequency(frequency):
    if frequency is None or frequency.lower() == "always":
        return None

    m = re.match(r"^(\d+)\s*(seconds?|minutes?|hours?|days?|weeks?)$", frequency)
    if not m:
        raise ValueError("Invalid frequency string: %s" % frequency)

    num = int(m.group(1))
    unit = m.group(2)
    if unit.startswith("second"):
        return datetime.timedelta(seconds=num)
    elif unit.startswith("minute"):
        return datetime.timedelta(minutes=num)
    elif unit.startswith("hour"):
        return datetime.timedelta(hours=num)
    elif unit.startswith("day"):
        return datetime.timedelta(days=num)
    elif unit.startswith("week"):
        return datetime.timedelta(weeks=num)
    else:
        raise ValueError("Invalid frequency unit: %s" % unit)

def parse_frequency(frequency):
    """
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    """
    if frequency is None or frequency == "always":
        return None
    match = re.match(r"^([0-9]*) ?([a-zA-Z]*)$", frequency)
    if not match:
        raise ValueError(f"Invalid frequency string: '{frequency}'")
    num = int(match.group(1))
    unit = match.group(2)
    if num == 0 or num < -1:
        raise ValueError(f"Invalid frequency value: {num}")
    if unit not in ["weeks", "days", "hours", "minutes", "seconds"]:
        raise ValueError(f"Invalid frequency unit: '{unit}'")
    return datetime.timedelta(**{unit: num})

