    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    """
    if frequency is None:
        return None
    if frequency.lower() == "always":
        return None
    try:
        num, unit = frequency.split()
        num = int(num)
        if unit == "week":
            delta = datetime.timedelta(weeks=num)
        elif unit == "day":
            delta = datetime.timedelta(days=num)
        elif unit == "hour":
            delta = datetime.timedelta(hours=num)
        elif unit == "minute":
            delta = datetime.timedelta(minutes=num)
        elif unit == "second":
            delta = datetime.timedelta(seconds=num)
        else:
            raise ValueError("Invalid unit of time")
        return delta
    except ValueError:
        raise ValueError("Invalid frequency string")

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    try:
        socket.inet_pton(socket.AF_INET, host)
    except socket.error:
        try:
            socket.inet_pton(socket.AF_INET6, host)
        except socket.error:
            return False
        return True
    return host == "127.0.0.1" or host == "::1"

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if host == 'localhost' or host == '127.0.0.1':
        return True
    else:
        return False

def make_find_paths(find_paths):
    TYPES = {'sh': '**/*{}*/**'}
    transformed = []
    for path in find_paths:
        if path.startswith(next(iter(TYPES))):
            transformed.append(path)
        else:
            for key, value in TYPES.items():
                transformed.append(value.format(path))
    return transformed

