        raise TypeError("'make_value' must be callable")
    if get_coordinate not in ["left", "right", "middle"]:
        raise ValueError("'get_coordinate' must be 'left', 'right' or 'middle'")
    if not isinstance(field_names, tuple) or len(field_names) != 2:
        raise ValueError("'field_names' must be a tuple of 2 strings")
    if not isinstance(scale, (bool, Scale)) and scale is not None:
        raise TypeError("'scale' must be 'None', 'True', 'False' or an instance of 'Scale'")

    # Get histogram attributes
    axes = hist.axes(True)
    title = hist.title()
    x_label = axes["x"].label()
    y_label = axes["y"].label()

    # Get coordinate and value functions
    if get_coordinate == "left":
        coordinate_fn = ops.identity
    elif get_coordinate == "right":
        coordinate_fn = lambda bin_: bin_.x + (bin_.xmin - bin_.x)
    else:
        coordinate_fn = lambda bin_: (bin_.x + bin_.xmin) / 2
    value_fn = lambda bin_: make_value(bin_.content)

    # Create a new graph
    graph = Graph(title=title, x_label=x_label, y_label=y_label, field_names=field_names)

    # Iterate over histogram bins and add data points to the graph
    for bin_ in hist.bins:
        coordinate = coordinate_fn(bin_)
        value = value_fn(bin_)
        graph.add_point(coordinate, value)

    # Set the scale of the graph
    if scale is None:
        graph.set_scale(hist.scale)
    elif scale is True:
        graph.set_scale(hist.scale)

    return graph

def _verify(iface, candidate, tentative=False, vtype=None):
    errors = []
    if not tentative:
        if not iface.providedBy(candidate):
            errors.append(Invalid(f'{candidate} does not provide interface {iface}'))
    for name, method in iface.namesAndDescriptions(bases=True):
        if name.startswith('_'):
            continue
        candidate_method = getattr(candidate, name, None)
        if candidate_method is None:
            errors.append(Invalid(f'{candidate} does not define method {name}'))
        else:
            iface_method = getattr(iface, name)
            try:
                signature = inspect.Signature.from_callable(candidate_method)
                iface_signature = inspect.Signature.from_callable(iface_method)
                if not _signatures_match(signature, iface_signature):
                    errors.append(Invalid(f'Method signature for {name} does not match'))
            except:
                pass
    for name, _ in iface.namesAndDescriptions(bases=True):
        if name in iface.names(bases=True):
            continue
        candidate_attr = getattr(candidate, name, None)
        if candidate_attr is None:
            errors.append(Invalid(f'{candidate} does not define attribute {name}'))
    if errors:
        if len(errors) == 1:
            raise errors[0]
        raise Invalid('\n'.join(str(error) for error in errors))
    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    # Step 1: Check if candidate is a class
    if not inspect.isclass(candidate):
        raise TypeError(f"{candidate} must be a class to verify.")

    # Step 2: Check if the candidate implements the interface
    if not issubclass(candidate, iface):
        raise TypeError(f"{candidate} does not implement the interface {iface}.")

    # Step 3: Check if the candidate has any additional attributes or methods not present in the interface
    for attr in dir(candidate):
        if not hasattr(iface, attr):
            raise TypeError(f"{candidate} has an attribute or method {attr} that is not present in the interface.")

    # Step 4: Check if the candidate's methods have the same signature as the interface's methods
    for method in dir(iface):
        if hasattr(candidate, method) and not inspect.ismethod(candidate, method):
            raise TypeError(f"{candidate} has a method {method} that does not have the same signature as the interface's method.")

    # Step 5: Check if the candidate's attributes have the same type as the interface's attributes
    for attr in dir(iface):
        if hasattr(candidate, attr) and not isinstance(getattr(candidate, attr), type(getattr(iface, attr))):
            raise TypeError(f"{candidate} has an attribute {attr} that does not have the same type as the interface's attribute.")

    # Step 6: Check if the candidate has any methods that are not present in the interface
    for method in dir(candidate):
        if not hasattr(iface, method):
            raise TypeError(f"{candidate} has a method {method} that is not present in the interface.")

    # Step 7: Check if the candidate has any attributes that are not present in the interface
    for attr in dir(candidate):
        if not hasattr(iface, attr):
            raise TypeError(f"{candidate} has an attribute {attr} that is not present in the interface.")

    # Step 8: If everything checks out, return True
    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    if not tentative:
        iface.verify(candidate)
    else:
        try:
            iface.verify(candidate)
        except (AttributeError, TypeError):
            raise VerificationError(f'{candidate} does not implement {iface} interface')

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    if not hasattr(candidate, '__bases__'):
        raise TypeError(f"{candidate} does not have __bases__ attribute")
    for base in candidate.__bases__:
        if iface in base.__bases__ or iface == base:
            return True
    if tentative:
        return False
    raise TypeError(f"{candidate} is not a subclass of {iface}")

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    # Verify that the candidate is a class
    if not inspect.isclass(candidate):
        raise TypeError(f"{candidate} is not a class")

    # Verify that the candidate implements all the methods and attributes defined in the interface
    for name in dir(iface):
        if name.startswith("__") and name.endswith("__"):
            continue
        iface_attr = getattr(iface, name)
        candidate_attr = getattr(candidate, name, None)
        if candidate_attr is None:
            raise AttributeError(f"{candidate} does not have an attribute named {name}")
        if not hasattr(candidate_attr, "__call__") and not hasattr(iface_attr, "__call__"):
            raise TypeError(f"{name} is not a method in {candidate} (or is not callable)")
        if callable(candidate_attr) and callable(iface_attr) and inspect.signature(candidate_attr) != inspect.signature(iface_attr):
            raise TypeError(f"{name} method in {candidate} has a different signature than the method in {iface}")

    # Verify that the candidate does not implement any extra methods or attributes that are not in the interface
    for name in dir(candidate):
        if name.startswith("__") and name.endswith("__"):
            continue
        if not hasattr(iface, name):
            raise AttributeError(f"{candidate} has an extra attribute named {name} that is not in {iface}")

    # If the candidate is not tentatively verified, we need to perform a deeper inspection
    if not tentative:
        # Verify that the candidate's methods are correctly implemented
        for name, candidate_method in inspect.getmembers(candidate, inspect.isfunction):
            if name.startswith("__") and name.endswith("__"):
                continue
            iface_method = getattr(iface, name, None)
            if iface_method is None:
                continue
            if not verifyMethod(iface_method, candidate_method):
                raise TypeError(f"{name} method in {candidate} is not correctly implemented")

        # Verify that the candidate's attributes are correctly implemented
        for name, candidate_attr in inspect.getmembers(candidate):
            if name.startswith("__") and name.endswith("__"):
                continue
            iface_attr = getattr(iface, name, None)
            if iface_attr is None:
                continue
            if not verifyAttribute(iface_attr, candidate_attr):
                raise TypeError(f"{name} attribute in {candidate} is not correctly implemented")

    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    # Check that the candidate is a type
    if not isinstance(candidate, type):
        raise TypeError("candidate must be a class")

    # Check that the candidate has the necessary attributes and methods
    for attr in iface.__annotations__:
        if not hasattr(candidate, attr):
            raise AttributeError(f"candidate is missing attribute {attr}")
        if not callable(getattr(candidate, attr)):
            raise TypeError(f"{attr} must be a method")

    # Check that the return type of the candidate's methods matches the expected return type
    for method, expected_return_type in iface.__annotations__.items():
        actual_return_type = getattr(candidate, method).__annotations__.get("return")
        if expected_return_type is not None and actual_return_type is not None:
            if not isinstance(expected_return_type, type) or not isinstance(actual_return_type, type):
                raise TypeError(f"Invalid return type for method {method}")
            if expected_return_type is not actual_return_type:
                raise TypeError(f"Return type {actual_return_type} of method {method} does not match "
                                f"expected return type {expected_return_type}")

    # If in tentative mode, we don't want to raise errors
    if tentative:
        return

    # If we've made it here without raising any errors, the candidate should be able to provide the interface
    return True

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        return explicit_mc
    if isinstance(bases, (list, tuple)):
        for base in bases:
            meta = getattr(base, "__metaclass__", None)
            if meta is not None:
                return meta
        return type
    return None

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if bases and any(isinstance(base, ClassDef) and base.hide for base in bases):
        metaclass = self.metaclass()
        if not metaclass:
            metaclass = next(
                base
                for base in bases
                if isinstance(base, ClassDef) and base.hide
            )
        elif explicit_mc and not isinstance(explicit_mc, ClassDef):
            explicit_mc = None
        return metaclass, explicit_mc
    else:
        return None, None

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        return explicit_mc
    metaclass = type
    for base in bases:
        if hasattr(base, "__metaclass__"):
            metaclass = base.__metaclass__
            break
    if metaclass is None:
        metaclass = type
    return metaclass

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    metaclass = None
    if explicit_mc is not None:
        metaclass = explicit_mc
    else:
        for base in bases:
            if metaclass is None:
                metaclass = base.metaclass
            else:
                metaclass = _getMetaclass(metaclass, base)
    return metaclass

def pop(self, key, default=None):
        """
        D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
        If key is not found, d is returned if given, otherwise KeyError is raised.
        """
        if key not in self:
            if default is not None:
                return default
            raise KeyError(key)

def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    if key in self:
        return self.get(key)
    elif default is not __marker:
        return default
    else:
        raise KeyError(key)

def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    logger.debug('call pop %s', key)
    try:
        value = self._pb.IntMap.pop(key)
    except KeyError:
        pass
    else:
        return value

    try:
        value = self._pb.FloatMap.pop(key)
    except KeyError:
