    else:
        return value

    try:
        value = self._pb.StringMap.pop(key)
    except KeyError:
        pass
    else:
        return value

    try:
        value = self._pb.BoolMap.pop(key)
    except KeyError:
        pass
    else:
        return value

    if default is not __marker:
        return default

    raise KeyError(key)

