def _create_in_regex(self) -> Pattern:
    """
    Create the in-style parameter regular expression.

    Returns the in-style parameter regular expression (:class:`re.Pattern`).
    """
    return re.compile(r"\s*in\s*:\s*(.*)$")

def _create_converter(self) -> _converting._Converter:
        """Create the parameter style converter.

        Returns the parameter style converter (:class:`._converting._Converter`).
        """
        ret = None
        # try to find the converter in the current module
        ret = getattr(self, "converter", None)
        if ret is None:
            # try to find the converter in the `__builtin__` module
            ret = getattr(__builtins__, "converter", None)
        if ret is None:
            # try to find the converter in the `__builtin__` module (python3)
            ret = getattr(builtins, "converter", None)
        if ret is None:
            # try to find the converter in the current module (again)
            ret = getattr(self, "converter", None)
        if ret is None:
            # try to find the converter in the `__builtin__` module (python3) (again)
            ret = getattr(builtins, "converter", None)
        if ret is None:
            # try to find the converter in any available modules
            ret = None
            for module in sys.modules.values():
                if hasattr(module, "converter"):
                    ret = getattr(module, "converter")
                    break
        if ret is None:
            raise ValueError("Specified converter not supported: {}".format(ret))
        return ret

def parse(self, timestr, default=None, ignoretz=False, tzinfos=None, **kwargs):
    """
    Parse the date/time string into a :class:`datetime.datetime` object.

    :param timestr:
        Any date/time string using the supported formats.

    :param default:
        The default datetime object, if this is a datetime object and not
        ``None``, elements specified in ``timestr`` replace elements in the
        default object.

    :param ignoretz:
        If set ``True``, time zones in parsed strings are ignored and a
        naive :class:`datetime.datetime` object is returned.

    :param tzinfos:
        Additional time zone names / aliases which may be present in the
        string. This argument maps time zone names (and optionally offsets
        from those time zones) to time zones. This parameter can be a
        dictionary with timezone aliases mapping time zone names to time
        zones or a function taking two parameters (``tzname`` and
        ``tzoffset``) and returning a time zone.

        The timezones to which the names are mapped can be an integer
        offset from UTC in seconds or a :class:`tzinfo` object.

        .. doctest::
           :options: +NORMALIZE_WHITESPACE

            >>> from dateutil.parser import parse
            >>> from dateutil.tz import gettz
            >>> tzinfos = {"BRST": -7200, "CST": gettz("America/Chicago")}
            >>> parse("2012-01-19 17:21:00 BRST", tzinfos=tzinfos)
            datetime.datetime(2012, 1, 19, 17, 21, tzinfo=tzoffset(u'BRST', -7200))
            >>> parse("2012-01-19 17:21:00 CST", tzinfos=tzinfos)
            datetime.datetime(2012, 1, 19, 17, 21,
                              tzinfo=tzfile('/usr/share/zoneinfo/America/Chicago'))

        This parameter is ignored if ``ignoretz`` is set.

    :param \\*\\*kwargs:
        Keyword arguments as passed to ``_parse()``.

    :return:
        Returns a :class:`datetime.datetime` object or, if the
        ``fuzzy_with_tokens`` option is ``True``, returns a tuple, the
        first element being a :class:`datetime.datetime` object, the second
        a tuple containing the fuzzy tokens.

    :raises ParserError:
        Raised for invalid or unknown string format, if the provided
        :class:`tzinfo` is not in a valid format, or if an invalid date
        would be created.

    :raises TypeError:
        Raised for non-string or character stream input.

    :raises OverflowError:
        Raised if the parsed date exceeds the largest valid C integer on
        your system.
    """
    if not timestr:
        raise ValueError("Invalid argument")

    if isinstance(timestr, bytes):
        timestr = timestr.decode(self.default_encoding)
    elif not isinstance(timestr, str):
        timestr = str(timestr)

    if default is None:
        default = datetime.datetime.now().replace(hour=0, minute=0, second=0, microsecond=0)

    if tzinfos is None:
        tzinfos = {}

    res = self._parse(timestr, **kwargs)

    if res is None:
        raise ValueError("Unknown string format: %s" % timestr)

    repl = {}
    for key, value in res.items():
        if key in ('year', 'month', 'day', 'hour', 'minute', 'second',
                   'microsecond', 'tzinfo', 'fold'):
            if value is None:
                repl[key] = getattr(default, key)
            else:
                repl[key] = value

    if 'weekday' in res and 'weekday_of_month' in res:
        repl['day'] = 1 + (repl['weekday'] - repl['weekday_of_month'])

    if 'weekday' in res and 'weekday_of_month' not in res and 'day_of_year' not in res:
        repl['day'] = 1 + ((repl['weekday'] - 1) % 7)

    if 'weekday_of_month' in res and 'weekday' not in res:
        repl['day'] = 1 + (repl['weekday_of_month'] - 1)

    if 'day_of_year' in res:
        repl['month'], repl['day'] = divmod(repl['day_of_year'] - 1, 30) + 1

    if 'quarter' in res:
        repl['month'] = (repl['quarter'] - 1) * 3 + 1

    if 'day' in repl and 'weekday' not in repl and 'weekday_of_month' not in repl:
        repl['weekday'] = (repl['day'] - 1) % 7 + 1

    if 'hour' in repl and 'meridiem' in res:
        if repl['meridiem'] == 'am' and repl['hour'] == 12:
            repl['hour'] = 0
        elif repl['meridiem'] == 'pm' and repl['hour'] < 12:
            repl['hour'] += 12

    for key, value in repl.items():
        if isinstance(value, str):
            value = value.replace('T', '').replace('Z', '')
            if ':' in value:
                hour, minute, second = value.split(':')
                try:
                    repl[key] = int(hour)
                except ValueError:
                    raise ValueError("Invalid time format: %s" % value)
                if minute.isdigit():
                    repl[key] = int(minute)
                if second.isdigit():
                    repl[key] = int(second)

    try:
        dt = datetime.datetime(**repl)
    except ValueError:
        raise ValueError("Invalid date/time format: %s" % timestr)

    if ignoretz:
        dt = dt.replace(tzinfo=None)
    elif 'tzinfo' in res and res['tzinfo'] == 'Z':
        dt = dt.replace(tzinfo=UTC)
    elif 'tzinfo' in res:
        tzinfo = res['tzinfo']
        if tzinfo in tzinfos:
            dt = dt.astimezone(tzinfos[tzinfo])
        else:
            raise ValueError("Invalid time zone: %s" % tzinfo)

    return dt

def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    # Private encrypted JSON payload
    try:
        data = json.loads(decode_if_bytes(request.body))
        if "encrypted_magic_envelope" in data:
            return True
    except Exception:
        pass
    # Public XML payload
    try:
        xml = etree.fromstring(encode_if_text(request.body))
        if xml.tag == MAGIC_ENV_TAG:
            return True
    except Exception:
        pass
    return False

