def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        document = json.loads(document)
    except Exception:
        pass
    if 'person' in document:
        person = document['person']
        if 'profile' in person:
            _webfinger = {'profile': person['profile']}
            _webfinger['hcard_url'] = person['hcard_url']
            _webfinger['node_url'] = person['node_url']
            return _webfinger
    raise ValueError('Document is not a valid Diaspora webfinger')

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if document.startswith("<"):
        # Parse XRD format
        xrd = xml.etree.ElementTree.fromstring(document)
        for link in xrd.findall("Link"):
            if "rel" in link.attrib and "lrdd" in link.attrib["rel"]:
                url = link.attrib.get("href")
                break
        else:
            url = None
    else:
        # Parse JSON format
        json_data = json.loads(document)
        url = json_data.get("links", {}).get("lrdd")

    if url is not None:
        return {"lrdd": url}
    else:
        return {}

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        document = json.loads(document)
    except ValueError:
        document = XRD.parseString(document)
    if isinstance(document, dict):
        return document
    else:
        raise ValueError("Invalid Diaspora webfinger format")

