def list_of_file_names(settings_dirs: list, spec_option: str) -> list:
    """Create a new IniType complex type

    :param settings_dirs: list of directories containing settings files
    :param spec_option: name of the specific option to search for
    :return: list of file names that contain the specified option
    """
    file_names = []
    for settings_dir in settings_dirs:
        for file in os.listdir(settings_dir):
            if file.endswith(".ini"):
                file_path = os.path.join(settings_dir, file)
                with open(file_path, "r") as f:
                    if spec_option in f.read():
                        file_names.append(file)
    return file_names

