    """Create a new IniType complex type
    """
    try:
        dirs = sorted(settings_dirs)
        files = []
        for dirname in dirs:
            for filename in os.listdir(dirname):
                if filename.endswith(spec_option):
                    files.append(os.path.join(dirname, filename))
        return files
    except OSError:
        return []

