    except ScannerError:
        raise IRValidatorException(f"YAML file {yaml_file} malformed")
    else:
        cls.validate_format(data)
        return data

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    if 'include' in parser_dict:
        include_dict = parser_dict.pop('include')
        for key, value in include_dict.items():
            if isinstance(value, dict):
                self._include_groups(value)
                parser_dict[key] = value
            else:
                parser_dict[key] = self.get_include_groups(value)

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    if not isinstance(parser_dict, dict):
        raise ValueError("parser_dict must be a dict")
    if "include" not in parser_dict:
        return
    include_spec = parser_dict["include"]
    if not isinstance(include_spec, list):
        raise ValueError("include spec must be a list")
    for include_item in include_spec:
        if not isinstance(include_item, str):
            raise ValueError("include spec items must be strings")
        include_item_lower = include_item.lower()
        if include_item_lower == "all":
            return
        group_name = None
        is_optional = False
        if ":" in include_item_lower:
            group_name, is_optional = include_item_lower.split(":", 1)
            if group_name == "":
                raise ValueError("Group name cannot be empty")
            if not is_optional.startswith("optional:"):
                raise ValueError("Invalid optional group format")
            is_optional, _, _ = is_optional.partition("optional:")
        else:
            group_name = include_item_lower
        if group_name not in self.groups:
            raise ValueError(f"Group {group_name} not found")
        if is_optional:
            self.groups[group_name].is_optional = is_optional
        else:
            self.groups[group_name].is_optional = None

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    if 'includes' not in parser_dict:
        return
    for include in parser_dict['includes']:
        if isinstance(include, dict):
            group = 'Include: ' + include['name']
            includes = include['includes']
            nested_parser_dict = {
                'name': group,
                'includes': includes
            }
            self._include_groups(nested_parser_dict)
            parser_dict['includes'] = nested_parser_dict
        elif include.endswith('.json'):
            with open(include, 'r') as f:
                self._include_groups(json.load(f))
        else:
            with open(include, 'r') as f:
                self._include_groups(yaml.safe_load(f))
        parser_dict['includes'] = parser_dict['includes'].get('includes', [])
        parser_dict['includes'].append(nested_parser_dict)

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files.

    :param dict parser_dict: The parser dictionary containing the include directive
    """
    if 'includes' in parser_dict:
        for include_file in parser_dict['includes']:
            include_parser_dict = self._parse_yaml_file(include_file)
            self._merge_parser_dicts(parser_dict, include_parser_dict)
            del parser_dict['includes']
    return parser_dict

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    resolved_specs = {}
    unresolved_specs = {}
    for arg_name, arg_value in self.spec.items():
        if not arg_name.startswith('_') and not isinstance(arg_value, _BaseOpt):
            if isinstance(arg_value, NoDefault):
                unresolved_specs[arg_name] = arg_value
            else:
                resolved_specs[arg_name] = arg_value
    for arg_name, arg_value in self.spec.items():
        if arg_name.startswith('_') and not isinstance(arg_value, _BaseOpt):
            if isinstance(arg_value, NoDefault):
                unresolved_specs[arg_name] = arg_value
            else:
                resolved_specs[arg_name] = arg_value
    return resolved_specs, unresolved_specs

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    # Get the default arguments from the function's code object
    defaults = self._get_defaults(self.spec)
    # Override the default arguments with the ones provided in spec
    for k, v in defaults.items():
        if k in self.spec.args and not isinstance(self.spec.args[k], NoDefault):
            v = self.spec.args[k]
    # Return the resolved argument values
    return defaults

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    try:
        # retrieve the default values from the spec
        spec_defaults = self._get_defaults(self.spec)
    except AttributeError:
        # if there is no spec, return an empty dictionary
        spec_defaults = {}

    try:
        # retrieve the default values from the _default_spec
        default_spec_defaults = self._get_defaults(self._default_spec)
    except AttributeError:
        # if there is no _default_spec, return an empty dictionary
        default_spec_defaults = {}

    # combine the spec and _default_spec defaults
    defaults = {**spec_defaults, **default_spec_defaults}

    try:
        # if there are any arg_defaults, add them to the defaults
        arg_defaults = self._arg_defaults.to_dict()
        defaults.update(arg_defaults)
    except AttributeError:
        # if there are no arg_defaults, do nothing
        pass

    return defaults

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    spec_defaults = {}
    for arg in self.args:
        if not isinstance(arg, _BaseOpt):
            raise errors.InvalidSchemeError('Unable to build default for non-Option type')
        # if there is a default set, add it to the spec_defaults dict
        if not isinstance(arg.default, NoDefault):
            spec_defaults[arg.name] = arg.default
        if isinstance(arg, DictOption):
            if arg.scheme:
                spec_defaults[arg.name] = arg.scheme.build_defaults()
    return spec_defaults

