    deprecated_args = {}

    # loop through the cli_args and determine if there are any deprecated arguments
    for arg in cli_args:
        if arg in DEPRECATED_ARGS:
            deprecated_args[arg] = cli_args[arg]

    # loop through the answer_file_args and determine if there are any deprecated arguments
    for arg in answer_file_args:
        if arg in DEPRECATED_ARGS:
            deprecated_args[arg] = answer_file_args[arg]

    # print a warning message for each deprecated argument
    for arg in deprecated_args:
        new_arg = DEPRECATED_ARGS[arg]
        print(f"WARNING: The argument '{arg}' is deprecated and will be removed in a future version. Please use '{new_arg}' instead.")

    # return the deprecated_args dict
    return deprecated_args

def validate_arg_deprecation(cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """

    # Check for deprecated arguments
    deprecated_args = []
    for arg, value in cli_args.items():
        if arg in answer_file_args:
            deprecated_args.append(arg)
            print(f"WARNING: '{arg}' is deprecated and will be removed in a future release. Use '{answer_file_args[arg]}' instead.")

