        if min_value > max_value:
            raise ValueError('Minimum value cannot be greater than maximum value.')

        for arg_name, arg_value in args.items():
            if arg_name not in ['min_value', 'max_value']:
                if arg_value < min_value or arg_value > max_value:
                    raise ValueError(f'Value of {arg_name} must be between {min_value} and {max_value}.')

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # get the function argspec
    argspec = getargspec(self)

    min_args = []
    max_args = []
    for arg in args:
        if arg in argspec.min_args:
            min_args.append(arg)
        elif arg in argspec.max_args:
            max_args.append(arg)
        else:
            raise TypeError("Invalid argument %s" % arg)

    for min_arg in min_args:
        if min_arg not in max_args:
            raise ValueError("minimum argument %s is not present in the maximum arguments" % min_arg)

    for max_arg in max_args:
        if max_arg not in min_args:
            raise ValueError("maximum argument %s is not present in the minimum arguments" % max_arg)

    for min_arg, max_arg in zip(min_args, max_args):
        if min_arg > max_arg:
            raise ValueError("maximum argument %s is smaller than the minimum argument %s" % (max_arg, min_arg))

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}
    custom_args = {}

    for arg in args:
        if arg.startswith('--control-'):
            control_args[arg[9:]] = args[arg]
        elif arg.startswith('--nested-') or arg.startswith('-- extra-parameters'):
            nested_args[arg[9:]] = args[arg]
        elif arg.startswith('--custom-'):
            custom_args[arg[9:]] = args[arg]

    return control_args, nested_args, custom_args

