def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if extra_vars is not None and isinstance(vars_dict, dict):
        for key, value in extra_vars.items():
            if key not in vars_dict:
                vars_dict[key] = value
            else:
                raise ValueError("Key '%s' already exists in dictionary" % key)
        return vars_dict
    else:
        raise ValueError("vars_dict must be a dictionary, got %s" % type(vars_dict))

def merge_extra_vars(vars_dict, extra_vars=None):
    if extra_vars is None:
        return vars_dict
    if not isinstance(extra_vars, list):
        raise ValueError("Unable to merge: List expected")
    for key in extra_vars:
        if key not in vars_dict:
            vars_dict[str(key)] = extra_vars[key]
    return vars_dict

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if extra_vars is not None:
        for name, value in extra_vars.items():
            if name not in vars_dict:
                vars_dict[name] = value
            else:
                existing_value = vars_dict[name]
                if isinstance(existing_value, list):
                    existing_value.extend(value)
                else:
                    vars_dict[name] = value
    return vars_dict

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if not extra_vars:
        return vars_dict

    # Convert the extra-vars to a dict
    extra_vars_dict = {}
    for extra_var in extra_vars:
        extra_vars_dict[extra_var] = vars_dict[extra_var]

    # Merge the extra-vars into the vars_dict
    vars_dict = {**vars_dict, **extra_vars_dict}

    return vars_dict

def ansible_playbook(self, ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
        """Wraps the 'ansible-playbook' CLI.

         :param ir_workspace: An Infrared Workspace object represents the active
         workspace
         :param ir_plugin: An InfraredPlugin object of the current plugin
         :param playbook_path: the playbook to invoke
         :param verbose: Ansible verbosity level
         :param extra_vars: dict. Passed to Ansible as extra-vars
         :param ansible_args: dict of ansible-playbook arguments to plumb down
             directly to Ansible.
        """

        if verbose:
            verbose = "-" + "v" * verbose
        command = "ansible-playbook"
        if verbose:
            command += " --verbosity %s" % verbose
        if self.plugin_dir:
            command += " --chdir %s" % self.plugin_dir
        if ir_plugin.name:
            command += " --plugin %s" % ir_plugin.name
        if playbook_path:
            command += " %s" % playbook_path
        if ir_workspace:
            command += " --extra-vars @%s" % ir_workspace.serialize()
        if extra_vars:
            extra_vars_path = os.path.join(self.temp_dir.name, "extra_vars.yaml")
            with open(extra_vars_path, "w+") as f:
                f.write(yaml.safe_dump(extra_vars))
            command += " --extra-vars @%s" % extra_vars_path
        if ansible_args:
            for k, v in ansible_args.items():
                command += " --%s %s" % (k, v)
        logger.debug("Running Ansible playbook: %s", command)
        output = subprocess.check_output(command, shell=True)
        return output.decode("utf-8")

